"""Small helpers plugins and the node process share."""
from __future__ import annotations

import json
from typing import Any, Dict


class RpcFailed(Exception):
    """Outbound RPC dropped, timed out, or the peer was unreachable."""


def mode(modes: Any, name: str) -> str:
    if modes is None:
        return ""
    return (getattr(modes, name, "") or "").strip()


def encode_store(store: Dict[bytes, bytes]) -> bytes:
    out = bytearray()
    for k, v in store.items():
        out += len(k).to_bytes(4, "big") + k + len(v).to_bytes(4, "big") + v
    return bytes(out)


def decode_store(blob: bytes) -> Dict[bytes, bytes]:
    store: Dict[bytes, bytes] = {}
    i = 0
    n = len(blob)
    while i + 8 <= n:
        lk = int.from_bytes(blob[i : i + 4], "big")
        i += 4
        k = blob[i : i + lk]
        i += lk
        lv = int.from_bytes(blob[i : i + 4], "big")
        i += 4
        v = blob[i : i + lv]
        i += lv
        store[k] = v
    return store


MAX_HOP = 8


def hop_count(request: Any) -> int:
    return int(getattr(request, "hop", 0) or 0)


def copy_with_hop(request: Any) -> Any:
    fwd = type(request)()
    fwd.CopyFrom(request)
    fwd.hop = hop_count(request) + 1
    return fwd


def encode_meta(obj: Dict[str, Any]) -> bytes:
    return json.dumps(obj, separators=(",", ":"), sort_keys=True).encode("utf-8")


def decode_meta(blob: bytes) -> Dict[str, Any]:
    if not blob:
        return {}
    try:
        got = json.loads(blob.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return {}
    return got if isinstance(got, dict) else {}
